-- ============================================================================
-- shop_customer_list_fast.sql
-- ============================================================================
-- Speeds up the customer /shops list by omitting inline data: URL images from the payload.
-- Run in Supabase Dashboard → SQL Editor after shop_owners / shop_products exist.
-- App falls back to column selects if these RPCs are missing.

create or replace function public.customer_shop_cards()
returns table (
  id uuid,
  business_name text,
  business_type text,
  business_address text,
  shop_image_url text
)
language sql
stable
security invoker
as $$
  select
    o.id,
    o.business_name,
    o.business_type,
    o.business_address,
    case
      when o.shop_image_url is null then null
      when o.shop_image_url like 'data:%' then null
      when length(o.shop_image_url) > 2048 then null
      else o.shop_image_url
    end as shop_image_url
  from public.shop_owners o
  where exists (
    select 1
    from public.shop_products p
    where p.shop_owner_id = o.id
      and p.is_active = true
  )
  order by o.business_name asc;
$$;

grant execute on function public.customer_shop_cards() to anon, authenticated;

drop function if exists public.customer_shop_product_shelf(integer);

create or replace function public.customer_shop_product_shelf(lim integer default 48)
returns table (
  id uuid,
  shop_owner_id uuid,
  name text,
  category text,
  brand_name text,
  price numeric,
  compare_at_price numeric,
  stock integer,
  is_active boolean,
  offers_free_delivery boolean,
  image_primary_url text,
  tags jsonb,
  created_at timestamptz
)
language sql
stable
security invoker
as $$
  select
    p.id,
    p.shop_owner_id,
    p.name,
    p.category,
    nullif(trim(p.brand_name), '') as brand_name,
    p.price,
    p.compare_at_price,
    p.stock,
    p.is_active,
    coalesce(p.offers_free_delivery, false) as offers_free_delivery,
    case
      when p.image_primary_url is null then null
      when p.image_primary_url like 'data:%' then null
      when length(p.image_primary_url) > 2048 then null
      else p.image_primary_url
    end as image_primary_url,
    coalesce(p.tags, '[]'::jsonb) as tags,
    p.created_at
  from public.shop_products p
  where p.is_active = true
  order by
    case when p.compare_at_price is not null and p.compare_at_price > p.price then 0 else 1 end,
    case when p.image_primary_url is not null and p.image_primary_url not like 'data:%' then 0 else 1 end,
    p.created_at desc nulls last,
    p.name asc
  limit greatest(1, least(coalesce(lim, 48), 120));
$$;

grant execute on function public.customer_shop_product_shelf(integer) to anon, authenticated;


